    int r0 = syscall(__NR_userfaultfd, 0x80001);
    struct uffdio_api api = { .api = UFFD_API, .features = 0 };
    ioctl(r0, UFFDIO_API, &api);
    struct uffdio_register reg = { .mode = UFFDIO_REGISTER_MODE_MISSING };
    reg.range.start = 0x200000000000;
    reg.range.len = 0x400000;
    ioctl(r0, UFFDIO_REGISTER, &reg);
    mremap((void*)0x200000000000, 0xc00000, 0x400000, MREMAP_MAYMOVE|MREMAP_FIXED, (void*)0x200000c00000);
    return 0;
}
